      <div class="pace-grid pace-two mt"><section class="glass pad"><h2>By subject · today</h2>${subjectRows.length?subjectRows.join(''):'<p class="mu">Your subject breakdown will appear after your first focus session.</p>'}<h2 class="pace-subhead">Distractions by category</h2>${categories.length?categories.map(([name,count])=>`<div class="pace-category"><span>${esc(name)}</span><b>${count}</b></div>`).join(''):'<p class="mu">No distractions logged today.</p>'}</section><section class="glass pad"><h2>Selected period</h2><div class="pace-chart" role="img" aria-label="Focus minutes by period">${days.map(d=>`<div><b>${Math.round(d.m)}m</b><i style="height:${Math.max(4,d.m/max*100)}%"></i><small>${d.label}</small></div>`).join('')}</div></section></div>
